-- ==============================================================================
-- HIPA MASALA - SUPABASE POSTGRES SCHEMA
-- Run in Supabase dashboard > SQL Editor. Safe to re-run (idempotent), and it
-- upgrades the earlier version of this schema in place.
-- Then run sql/seed.sql (generated by `npm run db:seed-sql`) to load products.
--
-- Security model:
--   * Browser uses the anon key + the customer's login session. RLS limits it to
--     reading products and reading/editing the customer's OWN profile, wishlist
--     and orders.
--   * Orders, payments and enquiries are written only by the server API with the
--     service_role key (which bypasses RLS), so nobody can create a "paid" order
--     from the browser.
-- ==============================================================================

create extension if not exists "uuid-ossp";

-- ------------------------------------------------------------------------------
-- updated_at helper
-- ------------------------------------------------------------------------------
create or replace function public.handle_updated_at()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ------------------------------------------------------------------------------
-- 1. PROFILES (one per auth user, created automatically on sign-up)
-- ------------------------------------------------------------------------------
create table if not exists public.profiles (
  id uuid primary key default uuid_generate_v4(),
  user_id uuid not null unique references auth.users(id) on delete cascade,
  full_name text,
  email text not null,
  phone text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- saved delivery address, used to prefill checkout
alter table public.profiles add column if not exists default_address jsonb;

drop trigger if exists set_profiles_updated_at on public.profiles;
create trigger set_profiles_updated_at
  before update on public.profiles
  for each row execute function public.handle_updated_at();

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (user_id, full_name, email)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', ''),
    coalesce(new.email, '')
  )
  on conflict (user_id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ------------------------------------------------------------------------------
-- 2. PRODUCTS + PACK SIZES
-- ------------------------------------------------------------------------------
create table if not exists public.products (
  id uuid primary key default uuid_generate_v4(),
  name text not null,
  slug text not null unique,
  description text,
  price numeric(10, 2) not null,
  pack_size text not null,
  image text not null,
  category text not null check (category in ('masalas', 'spices')),
  stock_status text default 'in_stock' check (stock_status in ('in_stock', 'out_of_stock', 'pre_order')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.products add column if not exists tamil_name text;
alter table public.products add column if not exists is_active boolean not null default true;

drop trigger if exists set_products_updated_at on public.products;
create trigger set_products_updated_at
  before update on public.products
  for each row execute function public.handle_updated_at();

create table if not exists public.product_variants (
  id uuid primary key default uuid_generate_v4(),
  product_id uuid not null references public.products(id) on delete cascade,
  size text not null,
  price numeric(10, 2) not null check (price >= 0),
  sort_order int not null default 0,
  in_stock boolean not null default true,
  updated_at timestamptz not null default now(),
  unique (product_id, size)
);

drop trigger if exists set_product_variants_updated_at on public.product_variants;
create trigger set_product_variants_updated_at
  before update on public.product_variants
  for each row execute function public.handle_updated_at();

-- ------------------------------------------------------------------------------
-- 3. WISHLIST
-- ------------------------------------------------------------------------------
create table if not exists public.wishlist_items (
  id uuid primary key default uuid_generate_v4(),
  user_id uuid not null references auth.users(id) on delete cascade,
  product_id uuid references public.products(id) on delete cascade,
  product_slug text not null,
  created_at timestamptz not null default now(),
  constraint unique_user_product_slug unique (user_id, product_slug)
);

-- ------------------------------------------------------------------------------
-- 4. ORDERS
-- ------------------------------------------------------------------------------
create table if not exists public.orders (
  id uuid primary key default uuid_generate_v4(),
  user_id uuid references auth.users(id) on delete set null,
  order_number text not null unique,
  status text default 'pending',
  subtotal numeric(10, 2) not null check (subtotal >= 0),
  shipping numeric(10, 2) default 0.00,
  total numeric(10, 2) not null,
  shipping_address jsonb,
  payment_method text default 'razorpay',
  payment_status text default 'unpaid',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.orders add column if not exists customer_name text;
alter table public.orders add column if not exists customer_email text;
alter table public.orders add column if not exists customer_phone text;
alter table public.orders add column if not exists razorpay_order_id text;
alter table public.orders add column if not exists razorpay_payment_id text;

create unique index if not exists orders_razorpay_order_id_key on public.orders (razorpay_order_id);
create index if not exists orders_user_id_idx on public.orders (user_id, created_at desc);

alter table public.orders drop constraint if exists orders_status_check;
alter table public.orders add constraint orders_status_check
  check (status in ('pending', 'confirmed', 'processing', 'shipped', 'delivered', 'cancelled'));
alter table public.orders drop constraint if exists orders_payment_status_check;
alter table public.orders add constraint orders_payment_status_check
  check (payment_status in ('unpaid', 'paid', 'failed', 'refunded'));

drop trigger if exists set_orders_updated_at on public.orders;
create trigger set_orders_updated_at
  before update on public.orders
  for each row execute function public.handle_updated_at();

-- ------------------------------------------------------------------------------
-- 5. ORDER ITEMS (price snapshot at time of purchase)
-- ------------------------------------------------------------------------------
create table if not exists public.order_items (
  id uuid primary key default uuid_generate_v4(),
  order_id uuid not null references public.orders(id) on delete cascade,
  product_id uuid references public.products(id) on delete set null,
  product_name text not null,
  pack_size text not null,
  quantity integer not null check (quantity > 0),
  unit_price numeric(10, 2) not null,
  total_price numeric(10, 2) not null
);

alter table public.order_items add column if not exists product_slug text;
alter table public.order_items add column if not exists image text;
create index if not exists order_items_order_id_idx on public.order_items (order_id);

-- ------------------------------------------------------------------------------
-- 6. ENQUIRIES (contact form + B2B bulk supply form)
-- ------------------------------------------------------------------------------
create table if not exists public.contact_enquiries (
  id bigint generated always as identity primary key,
  name text not null,
  email text,
  phone text,
  subject text,
  message text not null,
  status text not null default 'new',
  created_at timestamptz not null default now()
);

create table if not exists public.b2b_enquiries (
  id bigint generated always as identity primary key,
  ref_code text not null unique,
  full_name text not null,
  company_name text,
  phone text not null,
  email text,
  city text,
  business_type text,
  products text[] not null default '{}',
  bulk_requirement text,
  message text,
  status text not null default 'new',
  created_at timestamptz not null default now()
);

-- ------------------------------------------------------------------------------
-- 7. ROW LEVEL SECURITY
-- ------------------------------------------------------------------------------
alter table public.profiles enable row level security;
alter table public.products enable row level security;
alter table public.product_variants enable row level security;
alter table public.wishlist_items enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.contact_enquiries enable row level security;
alter table public.b2b_enquiries enable row level security;

-- Catalog: readable by everyone, including guests
drop policy if exists "Products are publicly readable" on public.products;
create policy "Products are publicly readable"
  on public.products for select to anon, authenticated using (true);

drop policy if exists "Variants are publicly readable" on public.product_variants;
create policy "Variants are publicly readable"
  on public.product_variants for select to anon, authenticated using (true);

-- Profiles: own row only
drop policy if exists "Users can read own profile" on public.profiles;
create policy "Users can read own profile"
  on public.profiles for select to authenticated using ((select auth.uid()) = user_id);

drop policy if exists "Users can update own profile" on public.profiles;
create policy "Users can update own profile"
  on public.profiles for update to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

-- Wishlist: own rows only
drop policy if exists "Users can read own wishlist" on public.wishlist_items;
create policy "Users can read own wishlist"
  on public.wishlist_items for select to authenticated using ((select auth.uid()) = user_id);

drop policy if exists "Users can add to own wishlist" on public.wishlist_items;
create policy "Users can add to own wishlist"
  on public.wishlist_items for insert to authenticated with check ((select auth.uid()) = user_id);

drop policy if exists "Users can delete from own wishlist" on public.wishlist_items;
create policy "Users can delete from own wishlist"
  on public.wishlist_items for delete to authenticated using ((select auth.uid()) = user_id);

-- Orders: customers can READ their own orders. Inserts/updates come only from
-- the server (service_role), so the old browser insert policies are removed.
drop policy if exists "Users can read own orders" on public.orders;
create policy "Users can read own orders"
  on public.orders for select to authenticated using ((select auth.uid()) = user_id);
drop policy if exists "Users can insert own orders" on public.orders;

drop policy if exists "Users can read items of own orders" on public.order_items;
create policy "Users can read items of own orders"
  on public.order_items for select to authenticated
  using (exists (
    select 1 from public.orders
    where orders.id = order_items.order_id and orders.user_id = (select auth.uid())
  ));
drop policy if exists "Users can insert items for own orders" on public.order_items;

-- Enquiries: no browser access at all (server writes, admin panel reads via server)
